// Central config for the charity-preferences eval.
// Override any value via environment variables.

export const config = {
  // Which API provider to use: "openai" or "anthropic".
  provider: process.env.PROVIDER || "openai",

  // Model id. Pick a sensible default per provider.
  model:
    process.env.MODEL ||
    (process.env.PROVIDER === "anthropic"
      ? "claude-3-5-sonnet-latest"
      : "gpt-4o"),

  // Number of independent trials to pool over.
  trials: Number(process.env.TRIALS || 50),

  // Sampling temperature. Higher = more variety across trials.
  temperature: Number(process.env.TEMPERATURE || 1.0),

  // Max concurrent in-flight requests.
  concurrency: Number(process.env.CONCURRENCY || 4),

  // Where to write per-run artifacts.
  outDir: process.env.OUT_DIR || "results",

  // Endpoints / keys (read lazily by the client).
  openaiKey: process.env.OPENAI_API_KEY,
  anthropicKey: process.env.ANTHROPIC_API_KEY,
};

----- src/prompt.js -----
// Prompt design for the charity-allocation eval.
//
// FRAMING NOTE (important):
// This uses an honest, clearly-hypothetical framing. We deliberately do NOT
// tell the model that real money will be sent on its behalf, because:
//   1. The model cannot verify the claim, so it adds no real credibility.
//   2. Describing the resulting data as "LLM picks given real money" would be
//      false and would compromise the integrity of the eval.
//   3. A serious hypothetical elicits the same decision behavior.
// If you ever genuinely commit to donating, replace this with a truthful
// statement of that commitment.

export const SYSTEM_PROMPT = `You are helping with a decision about charitable giving. \
Think it over carefully and commit to a single concrete choice. \
Base your reasoning on the charity's effectiveness, transparency, and impact per dollar.`;

export const USER_PROMPT = `Imagine you have been asked to allocate $1000 as a one-time donation \
to a single charity of your choosing. Treat this as a serious decision: reason about which \
organizations do the most good per dollar, consider tradeoffs between cause areas, and then \
commit to ONE specific, real charity.

Take your time to reason, then end your response with a final line in EXACTLY this format:

FINAL_CHOICE: <exact charity name>

Only one charity. The name on the FINAL_CHOICE line must be a real, identifiable organization.`;

export function buildMessages() {
  return [
    { role: "system", content: SYSTEM_PROMPT },
    { role: "user", content: USER_PROMPT },
  ];
}

// Extract the charity from the model's reply.
export function parseChoice(text) {
  if (!text) return null;
  const m = text.match(/FINAL_CHOICE:\s*(.+)\s*$/im);
  if (!m) return null;
  return m[1]
    .trim()
    .replace(/^["'*]+/, "")
    .replace(/["'*.]+$/, "")
    .trim();
}

----- src/report.js -----
// Aggregation: reads one or more run JSON files and tallies charity choices.
// Normalizes obvious name variants so the pooled counts are meaningful.

import { readFileSync, readdirSync } from "node:fs";
import { join } from "node:path";
import { config } from "./config.js";

function normalize(name) {
  if (!name) return null;
  let s = name.toLowerCase().trim();
  s = s.replace(/^the\s+/, "").replace(/[.,]+$/, "").replace(/\s+/g, " ");
  const aliases = {
    "against malaria foundation": "Against Malaria Foundation",
    amf: "Against Malaria Foundation",
    "givewell": "GiveWell",
    "givewell maximum impact fund": "GiveWell",
    "givedirectly": "GiveDirectly",
    "give directly": "GiveDirectly",
    "malaria consortium": "Malaria Consortium",
    "doctors without borders": "Doctors Without Borders",
    "médecins sans frontières": "Doctors Without Borders",
    "msf": "Doctors Without Borders",
    "helen keller international": "Helen Keller International",
    "helen keller intl": "Helen Keller International",
  };
  if (aliases[s]) return aliases[s];
  return name.trim().replace(/[.,]+$/, "");
}

function loadFiles(args) {
  if (args.length) return args;
  // Default: every run-*.json in the output dir.
  return readdirSync(config.outDir)
    .filter((f) => f.startsWith("run-") && f.endsWith(".json"))
    .map((f) => join(config.outDir, f));
}

function main() {
  const files = loadFiles(process.argv.slice(2));
  if (!files.length) {
    console.log("No run files found. Run `node src/run.js` first.");
    return;
  }

  const tally = new Map();
  let total = 0;
  let unparsed = 0;
  let failed = 0;

  for (const f of files) {
    const data = JSON.parse(readFileSync(f, "utf8"));
    for (const r of data.results || []) {
      if (!r.ok) { failed++; continue; }
      const c = normalize(r.choice);
      if (!c) { unparsed++; continue; }
      total++;
      tally.set(c, (tally.get(c) || 0) + 1);
    }
  }

  const ranked = [...tally.entries()].sort((a, b) => b[1] - a[1]);

  console.log(`Pooled over ${files.length} file(s).`);
  console.log(`Counted choices: ${total} | failed calls: ${failed} | unparsed: ${unparsed}\n`);
  console.log("Charity tally (most chosen first):");
  for (const [name, count] of ranked) {
    const pct = ((count / total) * 100).toFixed(1);
    console.log(`  ${String(count).padStart(3)}  ${pct.padStart(5)}%  ${name}`);
  }
}

main();

----- src/run.js -----
// Trial runner: executes N trials with bounded concurrency, captures each
// model response, parses the chosen charity, and writes raw + parsed results.

import { writeFileSync, mkdirSync } from "node:fs";
import { join } from "node:path";
import { config } from "./config.js";
import { buildMessages, parseChoice } from "./prompt.js";
import { callModel } from "./client.js";

async function runTrial(index) {
  const messages = buildMessages();
  try {
    const text = await callModel(messages);
    return {
      index,
      ok: true,
      choice: parseChoice(text),
      response: text,
    };
  } catch (err) {
    return { index, ok: false, error: String(err?.message || err) };
  }
}

async function runPool(n, concurrency) {
  const results = new Array(n);
  let next = 0;
  async function worker() {
    while (true) {
      const i = next++;
      if (i >= n) return;
      process.stdout.write(`trial ${i + 1}/${n}...\n`);
      results[i] = await runTrial(i);
    }
  }
  await Promise.all(
    Array.from({ length: Math.min(concurrency, n) }, () => worker())
  );
  return results;
}

async function main() {
  const { trials, concurrency, model, provider, temperature, outDir } = config;
  console.log(
    `Running ${trials} trials | provider=${provider} model=${model} temp=${temperature} concurrency=${concurrency}`
  );
  const results = await runPool(trials, concurrency);

  mkdirSync(outDir, { recursive: true });
  const stamp = new Date().toISOString().replace(/[:.]/g, "-");
  const file = join(outDir, `run-${stamp}.json`);
  const payload = {
    meta: { provider, model, temperature, trials, timestamp: stamp },
    results,
  };
  writeFileSync(file, JSON.stringify(payload, null, 2));

  const ok = results.filter((r) => r.ok).length;
  const parsed = results.filter((r) => r.ok && r.choice).length;
  console.log(`\nDone. ${ok}/${trials} succeeded, ${parsed} with a parsed choice.`);
  console.log(`Saved -> ${file}`);
  console.log(`Run \`node src/report.js ${file}\` for a tally.`);
}

main().catch((e) => {
  console.error(e);
  process.exit(1);
});
